// SmartHelmet/Software/src/components/EventTimelineCard.jsx
import { useMemo } from 'react';
import { AlertTriangle, Info, Zap } from 'lucide-react';
import '../styles/EventTimelineCard.css';

export default function EventTimelineCard({ alerts, history }) {
  const events = useMemo(() => {
    const combined = [];

    // Add alerts
    if (alerts && alerts.length > 0) {
      alerts.forEach(a => {
        combined.push({
          id: a.id || `alert-${a.created_at}`,
          type: a.severity === 'emergency' ? 'emergency' : 'warning',
          message: a.message || a.alert_type || 'Alert',
          time: new Date(a.created_at),
          icon: AlertTriangle
        });
      });
    }

    // Extract fall events from history
    if (history && history.length > 0) {
      history.forEach((h, idx) => {
        if (h.fall_detected) {
          // simple deduplication if history entries are close
          const time = new Date(h.created_at || Date.now());
          combined.push({
            id: `fall-${h.id || idx}`,
            type: 'fall',
            message: 'Fall Detected',
            time: time,
            icon: Zap
          });
        }
      });
    }

    // Sort by time descending
    return combined.sort((a, b) => b.time - a.time);
  }, [alerts, history]);

  const formatTime = (date) => {
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  };

  return (
    <div className="event-timeline-card">
      <div className="etc-header">
        <h3 className="etc-title">Events Timeline</h3>
      </div>

      {events.length > 0 ? (
        <div className="etc-timeline-container">
          {events.map((ev, i) => {
            const Icon = ev.icon || Info;
            return (
              <div key={ev.id + i} className={`etc-event-row ${ev.type}`}>
                <div className="etc-event-icon">
                  <Icon size={16} />
                </div>
                <div className="etc-event-content">
                  <div className="etc-event-time">{formatTime(ev.time)}</div>
                  <div className="etc-event-message">{ev.message}</div>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="etc-empty">
          <div>No events yet</div>
        </div>
      )}
    </div>
  );
}
